CREATE TABLE IF NOT EXISTS zukan_content_governance_events ( governance_event_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), action TEXT NOT NULL, target_kind TEXT NOT NULL, target_id UUID NOT NULL, requested_by_subject_id UUID REFERENCES zukan_subject_identities(subject_id) ON DELETE SET NULL, legal_basis TEXT, reason TEXT NOT NULL, effective_at TIMESTAMPTZ NOT NULL, recorded_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), metadata JSONB NOT NULL DEFAULT '{}'::jsonb, CHECK (action IN ('suppress', 'redact', 'erase')), CHECK (target_kind IN ('content_object', 'value_artifact', 'claim_revision', 'projection_snapshot', 'publication_edition')), CHECK (length(trim(reason)) > 0) ); CREATE TABLE IF NOT EXISTS zukan_snapshot_status_events ( snapshot_status_event_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), projection_snapshot_id UUID NOT NULL REFERENCES zukan_projection_snapshots(projection_snapshot_id) ON DELETE RESTRICT, governance_event_id UUID REFERENCES zukan_content_governance_events(governance_event_id) ON DELETE RESTRICT, reproducibility_status TEXT NOT NULL, affected_entry_keys JSONB NOT NULL DEFAULT '[]'::jsonb, recorded_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK (reproducibility_status IN ('full', 'redacted', 'degraded')), CHECK (jsonb_typeof(affected_entry_keys) = 'array') ); CREATE INDEX IF NOT EXISTS idx_zukan_snapshot_status_events_snapshot ON zukan_snapshot_status_events (projection_snapshot_id, recorded_at DESC); CREATE TABLE IF NOT EXISTS zukan_publication_availability_events ( publication_availability_event_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), publication_edition_id UUID NOT NULL REFERENCES zukan_publication_editions(publication_edition_id) ON DELETE RESTRICT, governance_event_id UUID REFERENCES zukan_content_governance_events(governance_event_id) ON DELETE RESTRICT, availability_status TEXT NOT NULL, effective_at TIMESTAMPTZ NOT NULL, recorded_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK (availability_status IN ('available', 'suppressed', 'withdrawn')) ); CREATE TABLE IF NOT EXISTS zukan_rights_evaluations ( rights_evaluation_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), content_object_id UUID REFERENCES zukan_content_objects(content_object_id) ON DELETE RESTRICT, value_artifact_id UUID REFERENCES zukan_value_artifacts(artifact_id) ON DELETE RESTRICT, purpose TEXT NOT NULL, basis TEXT NOT NULL DEFAULT 'unknown', evidence_content_object_id UUID REFERENCES zukan_content_objects(content_object_id) ON DELETE SET NULL, jurisdiction TEXT, valid_from TIMESTAMPTZ, valid_to TIMESTAMPTZ, basis_review_due TIMESTAMPTZ, inherited_from_rights_evaluation_id UUID REFERENCES zukan_rights_evaluations(rights_evaluation_id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK (purpose IN ('metadata', 'acquisition', 'preservation', 'processing', 'indexing', 'publication', 'redistribution', 'embedding', 'ai_input', 'model_training')), CHECK (basis IN ('allowed', 'denied', 'unknown')), CHECK ((content_object_id IS NOT NULL AND value_artifact_id IS NULL) OR (content_object_id IS NULL AND value_artifact_id IS NOT NULL)), CHECK (valid_to IS NULL OR valid_from IS NULL OR valid_to > valid_from) ); CREATE INDEX IF NOT EXISTS idx_zukan_rights_evaluations_due ON zukan_rights_evaluations (basis, purpose, basis_review_due) WHERE basis = 'unknown' OR basis_review_due IS NOT NULL; CREATE INDEX IF NOT EXISTS idx_zukan_rights_evaluations_content ON zukan_rights_evaluations (content_object_id, purpose, created_at DESC) WHERE content_object_id IS NOT NULL; CREATE INDEX IF NOT EXISTS idx_zukan_rights_evaluations_artifact ON zukan_rights_evaluations (value_artifact_id, purpose, created_at DESC) WHERE value_artifact_id IS NOT NULL;
